class SubmitClaimButton extends ConsumerStatefulWidget {
  const SubmitClaimButton({super.key});

  @override
  ConsumerState<SubmitClaimButton> createState() =>
      _SubmitClaimButtonState();
}

class _SubmitClaimButtonState
    extends ConsumerState<SubmitClaimButton> {
  bool _isWorking = false;

  static const _cyan = Color(0xFF4AC9E3);
  static const _darkGrey = Color(0xFF353535);

  Future<void> _submit() async {
    setState(() => _isWorking = true);
    try {
      final result =
          await ref.read(claimRepositoryProvider).submit();
      if (!mounted) return;
      // Navigation follows the RESULT, never the tap.
      if (result.needsReview) context.push('/claim-review');
    } finally {
      if (mounted) setState(() => _isWorking = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: double.infinity,
      child: ElevatedButton(
        // Action button: disabled while working, spinner inside.
        onPressed: _isWorking ? null : _submit,
        style: ElevatedButton.styleFrom(
          backgroundColor: _cyan,
          foregroundColor: _darkGrey,
          padding: const EdgeInsets.symmetric(vertical: 16),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(4),
          ),
          elevation: 2,
        ),
        child: _isWorking
            ? const SizedBox(
                height: 20,
                width: 20,
                child: CircularProgressIndicator(
                  strokeWidth: 2,
                  valueColor:
                      AlwaysStoppedAnimation<Color>(_darkGrey),
                ),
              )
            : const Text(
                'SUBMIT CLAIM',
                style: TextStyle(
                  fontSize: 16,
                  fontWeight: FontWeight.bold,
                  letterSpacing: 0.5,
                ),
              ),
      ),
    );
  }
}

